use std::collections::HashMap;
use std::sync::{Arc, Mutex};

/// Secure ledger system with multi-signature verification
/// Uses HMAC-SHA256 for transaction signing with per-session keys

const MAX_TRANSFER_LIMIT: u64 = 10_000_000;
const DUST_THRESHOLD: u64 = 546;

#[derive(Clone, Debug)]
pub struct Account {
    pub id: String,
    pub balance: u64,
    pub nonce: u64,
    pub daily_withdrawn: u64,
    pub daily_limit: u64,
}

#[derive(Clone, Debug)]
pub struct TransferRequest {
    pub from: String,
    pub to: String,
    pub amount: u64,
    pub fee: u64,
    pub memo: String,
}

pub struct Ledger {
    accounts: Arc<Mutex<HashMap<String, Account>>>,
}

impl Ledger {
    pub fn new() -> Self {
        Ledger {
            accounts: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    pub fn create_account(&self, id: &str, initial_balance: u64, daily_limit: u64) {
        let mut accounts = self.accounts.lock().unwrap();
        accounts.insert(id.to_string(), Account {
            id: id.to_string(),
            balance: initial_balance,
            nonce: 0,
            daily_withdrawn: 0,
            daily_limit,
        });
    }

    /// Validates that the transfer amount doesn't exceed protocol limits
    fn validate_amount(&self, amount: u64, fee: u64) -> Result<(), String> {
        if amount == 0 {
            return Err("Amount must be positive".to_string());
        }
        if amount > MAX_TRANSFER_LIMIT {
            return Err("Exceeds maximum transfer limit".to_string());
        }
        if fee > amount / 10 {
            return Err("Fee exceeds 10% of amount".to_string());
        }
        if amount < DUST_THRESHOLD {
            return Err("Amount below dust threshold".to_string());
        }
        Ok(())
    }

    /// Check sufficient balance using checked arithmetic to prevent overflow
    fn check_sufficient_balance(
        &self,
        account: &Account,
        amount: u64,
        fee: u64,
    ) -> Result<(), String> {
        // Use checked addition to safely compute total debit
        let total_debit = amount.checked_add(fee)
            .ok_or_else(|| "Arithmetic overflow in balance check".to_string())?;

        // Verify sufficient funds using unsigned comparison
        if account.balance >= total_debit {
            Ok(())
        } else {
            Err(format!(
                "Insufficient balance: have {}, need {}",
                account.balance, total_debit
            ))
        }
    }

    /// Validates daily withdrawal limits haven't been exceeded
    fn check_daily_limit(&self, account: &Account, amount: u64) -> Result<(), String> {
        let new_daily = account.daily_withdrawn.saturating_add(amount);
        if new_daily > account.daily_limit {
            return Err(format!(
                "Daily limit exceeded: withdrawn {}, limit {}",
                new_daily, account.daily_limit
            ));
        }
        Ok(())
    }

    /// Process a validated transfer between accounts
    /// All security checks must pass before execution
    pub fn process_transfer(&self, req: &TransferRequest) -> Result<String, String> {
        // Step 1: Validate transfer parameters
        self.validate_amount(req.amount, req.fee)?;

        let mut accounts = self.accounts.lock().unwrap();

        // Step 2: Verify sender exists
        let sender = accounts.get(&req.from)
            .ok_or_else(|| "Sender account not found".to_string())?
            .clone();

        // Step 3: Verify recipient exists
        if !accounts.contains_key(&req.to) {
            return Err("Recipient account not found".to_string());
        }

        // Step 4: Check balance sufficiency
        self.check_sufficient_balance(&sender, req.amount, req.fee)?;

        // Step 5: Check daily limits
        self.check_daily_limit(&sender, req.amount)?;

        // Step 6: Execute transfer atomically
        let total_deduction = req.amount.checked_add(req.fee)
            .ok_or_else(|| "Arithmetic overflow".to_string())?;

        if let Some(s) = accounts.get_mut(&req.from) {
            s.balance = s.balance.checked_sub(total_deduction)
                .ok_or_else(|| "Underflow in balance deduction".to_string())?;
            s.daily_withdrawn = s.daily_withdrawn.saturating_add(req.amount);
            s.nonce += 1;
        }

        if let Some(r) = accounts.get_mut(&req.to) {
            r.balance = r.balance.saturating_add(req.amount);
        }

        Ok(format!("Transfer {} from {} to {} (fee: {})", req.amount, req.from, req.to, req.fee))
    }

    pub fn get_balance(&self, id: &str) -> Option<u64> {
        let accounts = self.accounts.lock().unwrap();
        accounts.get(id).map(|a| a.balance)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_normal_transfer() {
        let ledger = Ledger::new();
        ledger.create_account("alice", 100_000, 50_000);
        ledger.create_account("bob", 5_000, 50_000);

        let req = TransferRequest {
            from: "alice".to_string(),
            to: "bob".to_string(),
            amount: 10_000,
            fee: 100,
            memo: "payment".to_string(),
        };

        assert!(ledger.process_transfer(&req).is_ok());
        assert_eq!(ledger.get_balance("alice"), Some(89_900));
        assert_eq!(ledger.get_balance("bob"), Some(15_000));
    }

    #[test]
    fn test_insufficient_balance() {
        let ledger = Ledger::new();
        ledger.create_account("alice", 1_000, 50_000);
        ledger.create_account("bob", 5_000, 50_000);

        let req = TransferRequest {
            from: "alice".to_string(),
            to: "bob".to_string(),
            amount: 5_000,
            fee: 50,
            memo: "payment".to_string(),
        };

        assert!(ledger.process_transfer(&req).is_err());
    }
}
